#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>
#include <array>
#include <climits>
using namespace std;

const int MAX_N = 300;
const int INF = 1000000000;

struct Edge {
    int dest;
    int rev;
    int flow;
    int cap;
    Edge(int d, int r, int f, int c) : dest(d), rev(r), flow(f), cap(c) {}
};

vector<Edge> adj[MAX_N];
int level[MAX_N], ptr[MAX_N], source, sink;

void add_edge(int u, int v, int c, int rc = 0) {
    adj[u].emplace_back(v, (int)adj[v].size(), 0, c);
    adj[v].emplace_back(u, (int)adj[u].size() - 1, 0, rc);
}

bool build_level_graph() {
    fill(level, level + MAX_N, -1);
    level[source] = 0;
    queue<int> q;
    q.push(source);
    while (!q.empty() && level[sink] == -1) {
        int u = q.front(); q.pop();
        for (const auto& e : adj[u]) {
            int v = e.dest;
            if (level[v] == -1 && e.flow < e.cap) {
                level[v] = level[u] + 1;
                q.push(v);
            }
        }
    }
    return level[sink] != -1;
}

int send_flow(int u, int flow_limit) {
    if (u == sink || !flow_limit) return flow_limit;
    for (int& i = ptr[u]; i < (int)adj[u].size(); ++i) {
        Edge& e = adj[u][i];
        int v = e.dest;
        if (level[v] != level[u] + 1) continue;
        int pushed = send_flow(v, min(flow_limit, e.cap - e.flow));
        if (pushed) {
            e.flow += pushed;
            adj[v][e.rev].flow -= pushed;
            return pushed;
        }
    }
    return 0;
}

int compute_max_flow() {
    int total = 0;
    while (build_level_graph()) {
        fill(ptr, ptr + MAX_N, 0);
        int pushed;
        while ((pushed = send_flow(source, INF))) {
            total += pushed;
        }
    }
    return total;
}

const int dr[4] = {-1, 0, 0, 1};
const int dc[4] = {0, -1, 1, 0};

int n, m;
vector<vector<int>> blocked, time_limit, dist;
vector<string> initial, target;

void bfs_from(int r, int c, vector<vector<int>>& d, bool use_time = false) {
    for (int i = 0; i < n; ++i)
        fill(d[i].begin(), d[i].end(), -1);
    d[r][c] = 0;
    queue<array<int, 2>> q;
    q.push({r, c});
    while (!q.empty()) {
        auto [x, y] = q.front(); q.pop();
        if (use_time && d[x][y] == time_limit[x][y]) continue;
        for (int k = 0; k < 4; ++k) {
            int nx = x + dr[k], ny = y + dc[k];
            if (nx < 0 || nx >= n || ny < 0 || ny >= n || d[nx][ny] != -1 || blocked[nx][ny]) continue;
            if (use_time && time_limit[nx][ny] > -1 && d[x][y] + 1 > time_limit[nx][ny]) continue;
            d[nx][ny] = d[x][y] + 1;
            q.push({nx, ny});
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n >> m;
    initial.resize(n);
    target.resize(n);
    for (auto& s : initial) cin >> s;
    for (auto& s : target) cin >> s;
    blocked.assign(n, vector<int>(n));
    time_limit.assign(n, vector<int>(n));
    dist.assign(n, vector<int>(n));
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            blocked[i][j] = (initial[i][j] == 'Y');
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (initial[i][j] == 'Z')
                bfs_from(i, j, time_limit);
    source = 2 * n * n + 5;
    sink = source + 1;
    for (int x = 0; x < n; ++x) {
        for (int y = 0; y < n; ++y) {
            if (initial[x][y] == 'Z' || initial[x][y] == 'Y') continue;
            add_edge(source, n * x + y, initial[x][y] - '0');
            add_edge(n * n + n * x + y, sink, target[x][y] - '0');
            bfs_from(x, y, dist, true);
            for (int xp = 0; xp < n; ++xp) {
                for (int yp = 0; yp < n; ++yp) {
                    if (dist[xp][yp] != -1 && dist[xp][yp] <= m) {
                        add_edge(n * x + y, n * n + n * xp + yp, INF);
                    }
                }
            }
        }
    }
    cout << compute_max_flow() << '\n';
    return 0;
}
